     output_img.copy(make_image(), 0, 0,Math.floor(R.random_num(250,synth_size)),Math.floor(R.random_num(250,synth_size)),Math.floor(WIDTH/2), Math.floor(HEIGHT/2), WIDTH, HEIGHT)
