   h_stripes_C = h
   num_horiz_stripes -= 1}
 var num_h_T = Math.floor(R.random_num(0,num_horiz_stripes+1))
 var num_h_B = num_horiz_stripes - num_h_T
 var y = 0
 var i = 0
 while (!got_all){
   got_all = true
   y = 0
   for (i = 0; i < num_h_T; i++){
