   var x = 0
   for (i = 0; i < num_v_L; i++){
     if (x > WIDTH/4) got_all = false
     x = Math.floor(R.random_num(x, WIDTH / 4))
     v_stripes[i] = x
     x += WIDTH/50}}
 got_all = false
